\end{equation}

For $s < t$,  the variational formula \eqref{eq:variational} yields

\begin{equation}\label{e.t,s difference variational formula}
	\mathfrak{h}_t(x) - \mathfrak{h}_s(x) = \sup_{y \in \mathbb{R}} \bigl\{ \mathfrak{h}_s(y) - \mathfrak{h}_s(x) + \mathcal{L}(y, s; x, t) \bigr\}.
\end{equation}

We wish to bound $\mathfrak{h}_s(y) -\mathfrak{h}_s(x)$ by $\mathcal C|y-x|^{1/2-\delta}$ for a random constant $\mathcal C$ uniform in $s\in[T_0,T]$ using Lemma~\ref{lem:Holder-space}. However, this requires that $y$ be restricted to a compact interval, and so we start by showing that we may localize the supremum in the previous display to a compact interval. More precisely, letting $y_{s,t}^*(x)$ be the maximizer of the supremum in \eqref{e.t,s difference variational formula} of minimum absolute value, we claim that, almost surely,

\begin{equation}\label{e.localize sup}
\sup_{|x|\leq L}\sup_{s\neq t\in[T_0, T]} |y_{s,t}^*(x)| < \infty.
\end{equation}

First let $R' = -\inf_{|x|\leq L}\inf_{s\in[T_0,T]} \mathfrak{h}_s(x)$. By the variational formula \eqref{eq:variational} and the continuity of $\mathcal{L}$, we have that $R'<\infty$ almost surely. Thus we see that

$$\sup_{y \in \mathbb{R}} \bigl\{ \mathfrak{h}_s(y) + \mathcal{L}(y, s; x, t) \bigr\} \geq \mathfrak{h}_s(x) + \mathcal{L}(x,s; x,t) \geq -R' + \inf_{|x|\leq L}\inf_{s\neq t\in[T_0,T]} \mathcal{L}(x,s; x,t) =: -R.$$

Bounds  \eqref{eq:Landscape_bound2} on $\mathcal{L}$ imply that $R<\infty$ almost surely; note that, by definition, $R$ is uniform over $|x|\leq L$ and $s,t\in[T_0,T]$. Thus, to prove \eqref{e.localize sup}, it is enough to show that there exists a random $M$ large enough such that, for all $s\neq t\in[T_0,T]$ and $|x|\leq L$,

\begin{equation}\label{e.defM}
\sup_{|y|\geq M} \bigl\{\mathfrak{h}_s(y) + \mathcal{L}(y,s; x,t) \bigr\} < -R.
\end{equation}

As in the proof of Lemma~\ref{lem:Holder-space}, this follows by using that $\mathcal{L}(y,s; x,t) \leq F_{1/3}(y,s,x,t) - \frac{(x-y)^2}{t-s}$ and a uniform decay estimate on $\mathfrak{h}_s(y)$. This decay estimate, provided by Lemma~\ref{lem:KPZ_is_bounded}, asserts that $\mathfrak{h}_s(y) \leq \mathcal{B} - \frac{1}{8}\min(t^{-1}, \sqrt{2}\gamma) |y|^{1/2} \leq \mathcal{B} - \frac{1}{8}\min(T^{-1}, \sqrt{2}\gamma) |y|^{1/2}$ for all $s,t\in[T_0, T]$ and $y\in \mathbb{R}$, where $\mathcal{B}$ is uniform over $s\in[T_0,T]$.

Thus, using the random $M$ which satisfies \eqref{e.defM} above, we see that \eqref{e.t,s difference variational formula} may be written as

\begin{equation}\label{e.difference variational formula 2}
\mathfrak{h}_t(x) - \mathfrak{h}_s(x) = \sup_{|y| \leq M} \bigl\{ \mathfrak{h}_s(y) - \mathfrak{h}_s(x) + \mathcal{L}(y, s; x, t) \bigr\}.
\end{equation}

Now, from Lemma~\ref{lem:Holder-space}, for given $\delta_1>0$, there exists a random constant $\mathcal C_1$ such that, for all $x,y \in[-M,M]$ and $s\in[T_0,T]$,

\begin{equation}\label{e.uniform space holder}
|\mathfrak{h}_s(y) - \mathfrak{h}_s(x)| \leq \mathcal C_1|y-x|^{\frac{1}{2}-\delta_1};
\end{equation}

though $M$ is random, we know such a random and a.s. finite constant $\mathcal C_1$ exists by applying Lemma~\ref{lem:Holder-space} on each of the events $M\in[m,m+1]$ for $m\in\mathbb{N}$ and getting a different random constant on eachof these disjoint events.

Applying this and bounds on $\mathcal L$ from \eqref{eq:Landscape_bound2} in \eqref{e.difference variational formula 2} yields, for $|x|\leq L$ and $s,t \in[T_0,T]$,

\begin{align*}
\mathfrak{h}_t(x)-\mathfrak{h}_s(x) &\leq \sup_{|y|\leq M} \left\{\mathcal C_1|y-x|^{\frac{1}{2}-\delta_1} + F_{\delta}(y,s,x,t)|t-s|^{\frac{1}{3}-\delta} - \frac{(x-y)^2}{t-s}\right\} \\

&\leq \sup_{|y|\leq M} \left\{\mathcal C_1|y-x|^{\frac{1}{2}-\delta_1} - \frac{(x-y)^2}{t-s}\right\} + F_{\delta}(M,T,L,T)|t-s|^{\frac{1}{3}-\delta}.
\end{align*}

Simple calculus yields that the supremum is at most $\mathcal C_2 |t-s|^{1/3-\delta_2}$ for a random constant $\mathcal C_2$, where $\delta_2 = 8\delta_1/(9+6\delta_1)$. We set $\delta_1$ so that $\delta_2$ equals the given positive value $\delta$ in Lemma~\ref{lem:Holder-time}, thus obtaining  $\mathfrak{h}_t(x)-\mathfrak{h}_s(x) \leq \mathcal C_3 |t-s|^{1/3-\delta}$ for a random constant $\mathcal C_3$ and for all $|x|\leq L$ and $s,t\in[T_0,T]$.

For the lower bound, again \eqref{e.uniform space holder} and \eqref{eq:Landscape_bound2} imply

\begin{align*}
\mathfrak{h}_t(x)-\mathfrak{h}_s(x) &\geq \sup_{|y|\leq M} \left\{-\mathcal C_1|y-x|^{\frac{1}{2}-\delta} - F_{\delta}(y,s,x,t)|t-s|^{\frac{1}{3}-\delta} - \frac{(x-y)^2}{t-s}\right\},\\

