\begin{equation}\label{eq:Qform}
\Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2) = - \int_{0}^{\delta_2} \mathrm{d} z \int_{-M + \varepsilon_2}^{\infty} \mathrm{d} v\; f_z(-M + \varepsilon_2) \,\cdot\, F^{(-M + \varepsilon_2)}_{[z, \delta_2]} (v) \,\cdot\, g_{\delta_2}(v),
\end{equation}
where we used the property $\mathbf{B} \bigl(\tau^{(-M + \varepsilon_2)}\bigr) = -M + \varepsilon_2$ and the fact that the ``No hit'' probability \eqref{eq:no_hit} is the same for the Brownian motion $\mathbf{B}$ with the reverse time direction. See Figure~\ref{Fig:Qform} for an illustration.


From Eq.~6.3 in Section~2.6 of \cite{karatzas1998brownian} for $z < \delta_2$ and $v > a$ we have the formula
\begin{equation}\label{eq:density_stopping_time2}
	F^{(a)}_{[z, \delta_2]} (v) = \frac{v - a}{\delta_2 - z} p_{\delta_2 - z} (v - a) = - 2 p'_{\delta_2 - z} (v - a),
\end{equation}
where $p'_{\ell} (u) = \partial_u p_{\ell} (u)$. For $z < \delta_2$, this function is continuously extended to $v = a$ by $0$. Combining this formula with \eqref{eq:Qform} and substituting it into \eqref{eq:Q_formula1} yields
\begin{equation}
	\begin{split}
	\MoveEqLeft[6]
	\Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2)\\
	&= 2 \int_{0}^{\delta_2} \mathrm{d} z \int_{-M + \varepsilon_2}^{\infty} \mathrm{d} v\; f_z(-M + \varepsilon_2) \,\cdot\, p'_{\delta_2 - z}(v + M - \varepsilon_2) \,\cdot\, g_{\delta_2}(v).
	\end{split}
\end{equation}
Since $f_z(-M) = 0$, we can write the preceding expression as
\begin{equation}
\begin{split}
\MoveEqLeft[6]
	\Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2)\\
	&= 	2 \varepsilon_2 \int_{0}^{\delta_2} \mathrm{d} z \int_{-M + \varepsilon_2}^{\infty} \mathrm{d} v\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p'_{\delta_2 - z}(v + M - \varepsilon_2) \,\cdot\, g_{\delta_2}(v).
\end{split}
\end{equation}
where $\nabla_{\!\varepsilon_2} f_z(v) = \frac{1}{\varepsilon_2} (f_z(v + \varepsilon_2) - f_z(v))$ is a difference quotient. Applying integration by parts to the integral with respect to $v$, we get
\begin{equation*}
\begin{split}
\MoveEqLeft[7]
	\Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2)\\
	&= 	- 2 \varepsilon_2 \int_{0}^{\delta_2} \mathrm{d} z\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p_{\delta_2 - z}(0) \,\cdot\, g_{\delta_2}(-M + \varepsilon_2)\\
	&\quad- 2 \varepsilon_2 \int_{0}^{\delta_2} \mathrm{d} z \int_{-M + \varepsilon_2}^{\infty} \mathrm{d} v\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p_{\delta_2 - z}(v + M - \varepsilon_2) \,\cdot\, g'_{\delta_2}(v),
\end{split}
\end{equation*}
where we used fast decay of the heat kernel at infinity. Hence, we have
\begin{equation}
\begin{split}
\MoveEqLeft[5]
	\frac{1}{|\eta_2|} \Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2)\\
	&= - \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p_{\delta_2 - z}(0) \,\cdot\, g_{\delta_2}(-M + \varepsilon_2)\\
	&\quad- \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{-M + \varepsilon_2}^{\infty} \mathrm{d} v\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p_{\delta_2 - z}(v + M - \varepsilon_2) \,\cdot\, g'_{\delta_2}(v).
\end{split}
\label{eq:Q_formula2}
\end{equation}
We denote these two terms by $\mathcal{I}^{(\eta_2)}_1$ and $\mathcal{I}^{(\eta_2)}_2$ respectively, and will compute their limits one by one.

\smallskip
\noindent {\bf The term $\mathcal{I}^{(\eta_2)}_1$.} From Lemma~\ref{lem:f_g}, we conclude that $|\nabla_{\!\varepsilon_2} f_z(-M)| \leq C_1$ uniformly in $\varepsilon_2 \in (0,1]$, $z \in [0, \frac{A}{2}]$ and $u_1 \in \mathbb{R}$. Furthermore, for $\alpha_\star$ from the definition \eqref{eq:Dom}, Lemma~\ref{lem:g_converges} gives the bound $|g_{\delta_2}(-M + \varepsilon_2)| \leq C_2 \varepsilon_2$ uniformly in $\delta_2 \in [0, \delta_\star]$, $\varepsilon_2 \in (0,\delta_2^{\alpha_\star}]$ and $u_2 \in \mathbb{R}$ (here, we use Lemma~\ref{lem:f_g}, which shows that $g_{\delta_2}$ has the required properties). Hence, for the constant $C = C_1 C_2 / \sqrt{\pi}$, we can bound
\begin{equation}
	|\mathcal{I}^{(\eta_2)}_1| \leq C \frac{1}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z\; \frac{\varepsilon_2}{\sqrt{\delta_2 - z}} = 2 C \frac{\varepsilon_2}{\sqrt{\delta_2}}.
\end{equation}
Since for $\eta_2 \in \mathsf{Dom}$ we have $\varepsilon_2 \leq \delta_2^{\alpha_\star}$ for $\alpha_\star > \frac{1}{2}$ (see \eqref{eq:Dom}), we conclude that
\begin{equation}\label{eq:I1_limit}
	\mylim{\eta_2 \searrow 0} |\mathcal{I}^{(\eta_2)}_1| \leq 2 C \lim_{\delta_2 \searrow 0} \delta_2^{\alpha_\star - \frac{1}{2}} = 0,
\end{equation}
uniformly in $u_1, u_2 \in \mathbb{R}$.

\smallskip
\noindent {\bf The term $\mathcal{I}^{(\eta_2)}_2$.} Changing the integration variable, we get
\begin{equation}
	\mathcal{I}^{(\eta_2)}_2 = \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{0}^{\infty} \mathrm{d} v\; \nabla_{\!\varepsilon_2} f_z(-M) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2).
\end{equation}
Let us define $\mathcal{I}_2 = f'_0(-M) \cdot g'_{0}(-M)$ and
\begin{equation}\label{eq:I2_tilde}
	\widetilde{\mathcal{I}}^{(\delta_2)}_2 = \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{0}^{\infty} \mathrm{d} v\; f'_z(-M) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M).
\end{equation}
We are going to prove that $\mathcal{I}^{(\eta_2)}_2 - \widetilde{\mathcal{I}}^{(\delta_2)}_2$ vanishes and $\widetilde{\mathcal{I}}^{(\delta_2)}_2$ converges to $\mathcal{I}_2$ as $\eta_2 \searrow 0$ in the domain $\mathsf{Dom}$.

We first prove that $\mathcal{I}^{(\eta_2)}_2 - \widetilde{\mathcal{I}}^{(\delta_2)}_2$ vanishes as $\eta_2 \searrow 0$ along $\mathsf{Dom}$. We have
\begin{align}
\MoveEqLeft
	\mathcal{I}^{(\eta_2)}_2 - \widetilde{\mathcal{I}}^{(\delta_2)}_2 \\
	&=\, \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{0}^{\infty} \mathrm{d} v\; \bigl(\nabla_{\!\varepsilon_2} f_z(-M) - f'_z(-M)\bigr) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\\
	&\quad+ \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{0}^{\infty} \mathrm{d} v\; f'_z(-M) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, \bigl(g'_{\delta_2}(v - M + \varepsilon_2) - g'_{\delta_2}(v - M)\bigr).
\end{align}
Denote these two terms by $\mathcal{I}^{(\eta_2)}_{2, 1}$ and $\mathcal{I}^{(\eta_2)}_{2, 2}$ respectively; we will show that they both vanish in the limit.

\smallskip
\noindent{\bf The term $\mathcal{I}^{(\eta_2)}_{2,1}$.} We can bound
\begin{equation}
\begin{split}
|\mathcal{I}^{(\eta_2)}_{2, 1}|
 &\leq \Big(\sup_{0 \leq z \leq \delta_2} \bigl|\nabla_{\!\varepsilon_2} f_z(-M) - f'_z(-M)\bigr|\Big)\\
 &\qquad\times \frac{2}{\delta_2} \int_{0}^{\delta_2}\!\!\! \mathrm{d} z \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right|.
 \end{split}\label{eq:I21}
\end{equation}
From Lemma~\ref{lem:f_g} we get
\begin{equation}\label{eq:f_vanishes}
	\lim_{\varepsilon_2 \searrow 0} \sup_{0 \leq z \leq \delta_2} \bigl|\nabla_{\!\varepsilon_2} f_z(-M) - f'_z(-M)\bigr| = 0.
\end{equation}
Moreover, the monotonicity property of the Riemann integral gives
\begin{align}
\MoveEqLeft[6]
	\lim_{\delta_2 \searrow 0} \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \frac{1}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right| \\
	& \leq \lim_{\delta_2 \searrow 0} \frac{1}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z\; \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right|.
\end{align}
From boundedness and continuity of the function $g'_{\delta_2}$ (Lemma~\ref{lem:f_g}) we conclude that the function
\begin{equation}
	z  \mapsto  \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right|
\end{equation}
is continuous in $z \in (0, \delta_2]$. Then the fundamental theorem of calculus and Lemma~\ref{lem:heat2} yield
\begin{equation}
	\begin{split}
	\MoveEqLeft[7]
	\lim_{\delta_2 \searrow 0} \frac{1}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z\; \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right| \\
		&=\lim_{\delta_2 \searrow 0} \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \left|\int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2}(v) \,\cdot\, g'_{\delta_2}(v - M + \varepsilon_2)\right| \\
		&\leq \lim_{\delta_2 \searrow 0} \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2}(v) \,\cdot\, |g'_{\delta_2}(v - M + \varepsilon_2)| = \frac{1}{2} |g'_{0}(- M)|,
	\end{split}\label{eq:I21_intermediate}
\end{equation}
for $\alpha_\star$ from \eqref{eq:Dom}. From Lemma~\ref{lem:f_g} we conclude that all these limits hold uniformly in $u_1, u_2 \in \mathbb{R}$. Using \eqref{eq:I21_intermediate} together with \eqref{eq:f_vanishes} and \eqref{eq:I21} yields
\begin{equation}\label{eq:I21_limit}
	\mylim{\eta_2 \searrow 0} |\mathcal{I}^{(\eta_2)}_{2,1}| = 0,
\end{equation}
uniformly in $u_1, u_2 \in \mathbb{R}$.

\smallskip
\noindent{\bf The term $\mathcal{I}^{(\eta_2)}_{2,2}$.} We bound
\begin{equation}\label{eq:I22}
\begin{split}
	|\mathcal{I}^{(\eta_2)}_{2, 2}| &\leq \Big( \sup_{0 \leq z \leq \delta_2} |f'_z(-M)|\Big)\\
	&\qquad\times \frac{2}{\delta_2} \int_{0}^{\delta_2}\!\!\! \mathrm{d} z \left|\int_{0}^{\infty}\!\!\! \mathrm{d} v\; p_{\delta_2 - z}(v) \,\cdot\, \bigl(g'_{\delta_2}(v - M + \varepsilon_2) - g'_{\delta_2}(v - M)\bigr)\right|.
\end{split}
\end{equation}
Lemma~\ref{lem:f_g} implies that the supremum of $|f'_z(-M)|$ in \eqref{eq:I22} is bounded, and the function
\begin{equation}
	z  \mapsto  \int_{0}^{\infty} \mathrm{d} v\;  p_{\delta_2 - z}(v) \,\cdot\, \bigl(g'_{\delta_2}(v - M + \varepsilon_2) - g'_{\delta_2}(v - M)\bigr)
\end{equation}
is continuous in $z \in (0, \delta_2]$. Then, in the same way as in \eqref{eq:I21_intermediate}, the fundamental theorem of calculus and Lemma~\ref{lem:heat2} give
\begin{align}
\MoveEqLeft[6]
	\lim_{\delta_2 \searrow 0} \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \frac{1}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \left|\int_{0}^{\infty} \mathrm{d} v\; p_{\delta_2 - z}(v) \,\cdot\, \bigl(g'_{\delta_2}(v - M + \varepsilon_2) - g'_{\delta_2}(v - M)\bigr)\right|\\
	&= \lim_{\delta_2 \searrow 0} \sup_{0 \leq \varepsilon_2 \leq \delta_2^{\alpha_\star}} \left|\int_{0}^{\infty} \mathrm{d} v\; p_{\delta_2}(v) \,\cdot\, \bigl(g'_{\delta_2}(v - M + \varepsilon_2) - g'_{\delta_2}(v - M)\bigr)\right| = 0.
\end{align}
From Lemma~\ref{lem:f_g} we conclude that this limit and the bounds hold uniformly in $u_1, u_2 \in \mathbb{R}$. Using this limit in \eqref{eq:I22}, we see that
\begin{equation}\label{eq:I22_limit}
	\mylim{\eta_2 \searrow 0} |\mathcal{I}^{(\eta_2)}_{2,2}| = 0.
\end{equation}
From \eqref{eq:I21_limit} and \eqref{eq:I22_limit}, we conclude that $\mylim{\eta_2 \searrow 0} \bigl|\mathcal{I}^{(\eta_2)}_2 - \widetilde{\mathcal{I}}^{(\delta_2)}_2 \bigr| = 0$ uniformly in $u_1, u_2 \in \mathbb{R}$.

We now prove that $\widetilde{\mathcal{I}}^{(\delta_2)}_2$ converges to $\mathcal{I}_2$ as $\eta_2 \searrow 0$. From Lemma~\ref{lem:f_g}, we conclude that the function
\begin{equation}
	z  \mapsto   \int_{0}^{\infty} \mathrm{d} v\; f'_z(-M) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M)
\end{equation}
is continuous in $z \in (0, \delta_2]$. Then applying the fundamental theorem of calculus and Lemma~\ref{lem:heat2} to \eqref{eq:I2_tilde}, we get
\begin{align}\label{eq:I2_limit}
	\lim_{\delta_2 \searrow 0} \widetilde{\mathcal{I}}^{(\delta_2)}_2 &= \lim_{\delta_2 \searrow 0} \frac{2}{\delta_2} \int_{0}^{\delta_2} \mathrm{d} z \int_{0}^{\infty} \mathrm{d} v\; f'_z(-M) \,\cdot\, p_{\delta_2 - z}(v) \,\cdot\, g'_{\delta_2}(v - M)\\
	&= \lim_{\delta_2 \searrow 0} 2 \int_{0}^{\infty} \mathrm{d} v\; f'_0(-M) \,\cdot\, p_{\delta_2}(v) \,\cdot\, g'_{\delta_2}(v - M) = \mathcal{I}_2.
\end{align}
As before we conclude that the limit holds uniformly in $u_1, u_2 \in \mathbb{R}$.

From \eqref{eq:I1_limit} and \eqref{eq:I2_limit}, we obtain
\begin{equation}
	\begin{split}
	\MoveEqLeft[8]
	\mylim{\eta_2 \searrow 0} \frac{1}{|\eta_2|} \Bigl(\mathbf{Q}_L^{(\eta_1; \eta_2)} - \mathbf{Q}_L^{(\eta_1; 0)}\Bigr)(u_1, u_2)\\
	&= - f'_0(-M) \cdot g'_{0}(-M)\\
	&= -\partial_{2} \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} (u_1, -M)\,\cdot\,\partial_{1} \Theta^{(-M)}_{[x_2, L]} (-M, u_2),
	\end{split}\label{eq:Q1_limit_proof}
\end{equation}
uniformly in $u_1, u_2 \in \mathbb{R}$, which is the required formula \eqref{eq:Q_eps1_0_formula}.

 Dependence of the prelimiting kernel on $\eta_1$ is only through the function $\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})}$ and  its $\partial_{2}$-derivative, which appear in \eqref{eq:Q_eps1_0_formula} and other formulas. From \eqref{eq:f_explicitly}, we can see that these functions are bounded uniformly in $\eta_1 \in (0, \frac{A}{2}]^2$; indeed, the kernel $\mathbf{P}_{[-L,x_1 + \delta_1]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})}$ is bounded because it is a density function, and boundedness of $\partial_{2} \Theta^{(-M)}_{[x_1 + \delta_1, x_2]}$ follows from \eqref{e:Theta_formula}. Hence, the limit \eqref{eq:Q_eps1_0} holds uniformly over $\eta_1 \in (0, \frac{A}{2}]^2$.

One can readily see that the limit \eqref{eq:Q_eps1_0} holds also uniformly over $(x_1, x_2) \in S$ and $M \in \bar S$. This is because all the involved kernels are given by hitting and transition distributions of Brownian motion, which are bounded uniformly in these variables. This finishes the proof of \eqref{eq:Q_eps1_0} and \eqref{eq:Q_eps1_0_formula}.
\smallskip

A proof of existence of the limit \eqref{eq:Q_0_eps2} and the formula \eqref{eq:Q_0_eps2_formula} is carried out in a similar manner. Indeed, we may write
\begin{align}
\frac{\Bigl(\mathbf{Q}_L^{(\eta_1; 0)} - \mathbf{Q}_L^{(0; 0)}\Bigr)(u_1, u_2)}{p_{2 L}(u_2 - u_1)} =& \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(L) = u_2}\Bigl(\mathbf{B}(y)>-\mathfrak{g}_{\eta_1, 0}(y) \text{ for } y \in [-L,L]\Bigr) \\
&- \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(L) = u_2}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,L]\Bigr)\\
=& - \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(L) = u_2}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,L],\, \\
& \hspace{0.5cm} \mathbf{B}(z) \in (-M, -M + \varepsilon_1] \text{ for some } z \in [x_1, x_1 + \delta_1)\Bigr).
\end{align}
Defining the stopping time $\bar{\tau}^{(a)} := \sup \{z < x_1 + \delta_1: \mathbf{B}(z) = a\}$, as in \eqref{eq:Q_formula1} we write
\begin{align}
\frac{\Bigl(\mathbf{Q}_L^{(\eta_1; 0)} - \mathbf{Q}_L^{(0; 0)}\Bigr)(u_1, u_2)}{p_{2 L}(u_2 - u_1)}
&= - \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(L)=u_2}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,L],\, \\
& \hspace{4.5cm} \bar{\tau}^{(-M + \varepsilon_1)} \in [x_1, x_1 + \delta_1)\Bigr).\label{eq:Q2_stopping_time}
\end{align}
Then, as in \eqref{eq:Q_formula2}, we may show that
\begin{align}
	\frac{1}{|\eta_1|} \Bigl(\mathbf{Q}_L^{(\eta_1; 0)} &- \mathbf{Q}_L^{(0; 0)}\Bigr)(u_1, u_2) = - \frac{2}{\delta_1} \int_{0}^{\delta_1} \mathrm{d} z\; \nabla_{\!\varepsilon_1} \bar{f}_z(-M) \,\cdot\, p_{\delta_1 - z}(0) \,\cdot\, \bar{g}_{\delta_1}(-M + \varepsilon_1)\\
	&- \frac{2}{\delta_1} \int_{0}^{\delta_1} \mathrm{d} z \int_{-M + \varepsilon_1}^{\infty} \mathrm{d} v\; \nabla_{\!\varepsilon_1} \bar{f}_z(-M) \,\cdot\, p_{\delta_1 - z}(v + M - \varepsilon_1) \,\cdot\, \bar{g}'_{\delta_1}(v),
\end{align}
where
\begin{equation}
	\bar{f}_\delta(v) = \Theta^{(-M)}_{[-L, x_1 + \delta]} (u_1, v), \qquad \bar{g}_{\delta}(v) = \Theta^{(-M)}_{[x_1 + \delta, L]} (v, u_2).
\end{equation}
Since these function are particular cases of the functions \eqref{eq:functions_f_g}, we can repeat the argument used in our derivation of \eqref{eq:Q1_limit_proof}. This shows that
\begin{align}
	\mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} \Bigl(\mathbf{Q}_L^{(\eta_1; 0)} - \mathbf{Q}_L^{(0; 0)}\Bigr)(u_1, u_2) &= - \bar{f}'_0(-M) \cdot \bar{g}'_{0}(-M)\\
	&= -\partial_{2} \Theta^{(-M)}_{[-L, x_1]} (u_1, -M) \,\cdot\, \partial_{1} \Theta^{(-M)}_{[x_1, L]} (-M, u_2).\label{eq:Q1_limit_formula}
\end{align}
Uniformity of this limit over $(x_1, x_2) \in S$, $u_1, u_2 \in \mathbb{R}$ and $M \in \bar S$ can be seen as in \eqref{eq:Q1_limit_proof}. This finishes the proof of \eqref{eq:Q_0_eps2} and \eqref{eq:Q_0_eps2_formula}. To prove \eqref{eq:Q_0_0}, we also need the limit
\begin{equation}
\begin{split}
\MoveEqLeft[6]
	\mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} \partial_2 \Bigl(\mathbf{Q}_L^{(\eta_1; 0)} - \mathbf{Q}_L^{(0; 0)}\Bigr)(u_1, u_2)\\
	&= -\partial_{2} \Theta^{(-M)}_{[-L, x_1]} (u_1, -M) \,\cdot\, \partial_{1} \partial_{2} \Theta^{(-M)}_{[x_1, L]} (-M, u_2),
\end{split}
\label{eq:Q1_limit_formula_derivative}
\end{equation}
which can be proved by repeating the proof of \eqref{eq:Q1_limit_formula}.
\smallskip

Now, we turn to the proof of existence of the last limit \eqref{eq:Q_0_0} and the formula \eqref{eq:Q_0_0_formula}. Using \eqref{eq:Q1_limit_proof}, we obtain
\begin{equation}\label{eq:Q_star_formula}
\begin{split}
\MoveEqLeft[3]
\Bigl(\mathbf{Q}_L^{(\eta_1; \star)} - \mathbf{Q}_L^{(0; \star)}\Bigr) (u_1, u_2)\\
&= \partial_{2} \Bigl(\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} - \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-M)} \Bigr) (u_1, -M) \,\cdot\, \partial_{1} \Theta^{(-M)}_{[x_2, L]} (-M, u_2).
\end{split}
\end{equation}
We may assume that $x_1 + \delta_1 < x_2$. Using \eqref{eq:no_hit}, we may write the kernel in parentheses explicitly:
\begin{align}
\MoveEqLeft[11]
\frac{\Bigl(\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} - \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-M)} \Bigr) (u_1, v_1)}{p_{x_2 + L}(v_1 - u_1)}\\
=&\, \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(x_2) = v_1}\Bigl(\mathbf{B}(y)>-\mathfrak{g}_{\eta_1, 0}(y) \text{ for } y \in [-L,x_2]\Bigr) \\
& - \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(x_2) = v_1}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,x_2]\Bigr)\\
=& - \mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(x_2) = v_1}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,x_2],\, \\
& \hspace{0.5cm} \mathbf{B}(z) \in (-M, -M + \varepsilon_1] \text{ for some } z \in [x_1, x_1 + \delta_1)\Bigr).
\end{align}
As in \eqref{eq:Q2_stopping_time}, we can write
\begin{align}
\MoveEqLeft[2]
\frac{\Bigl(\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} - \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-M)} \Bigr) (u_1, v_1)}{p_{x_2 + L}(v_1 - u_1)} \\
=&-\mathbb P_{\mathbf{B}(-L)=u_1, \mathbf{B}(x_2)=u_2}\Bigl(\mathbf{B}(y)>-M \text{ for } y \in [-L,x_2],\, \bar{\tau}^{(-M + \varepsilon_1)} \in [x_1, x_1 + \delta_1)\Bigr).
\end{align}
This formula is the same as \eqref{eq:Q2_stopping_time}, where the interval is $[-L, x_2]$ instead of $[-L, L]$ . In the same way as in \eqref{eq:Q1_limit_formula_derivative}, we arrive at
\begin{align}
\MoveEqLeft[11]
\mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} \partial_{2} \Bigl(\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} - \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-M)}\Bigr)(u_1, v_1)\\
&= -\partial_{2} \Theta^{(-M)}_{[-L, x_1]} (u_1, -M) \,\cdot\, \partial_{1} \partial_{2} \Theta^{(-M)}_{[x_1, x_2]} (-M, v_1).
\end{align}
Using this limit in \eqref{eq:Q_star_formula}, we obtain
\begin{align}
\mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} &\Bigl(\mathbf{Q}_L^{(\eta_1; \star)} - \mathbf{Q}_L^{(0; \star)}\Bigr) (u_1, u_2) \\
&= \mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} \partial_{2} \Bigl(\mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, 0})} - \mathbf{P}_{[-L,x_2]}^{\uptext{No\! hit}\,(-M)} \Bigr) (u_1, -M) \,\cdot\, \partial_{1} \Theta^{(-M)}_{[x_2, L]} (-M, u_2)\\
&= -\partial_{2} \Theta^{-M}_{[-L, x_1]} (u_1, -M) \,\cdot\, \partial_{1} \partial_{2} \Theta^{(-M)}_{[x_1, x_2]} (-M, -M) \,\cdot\, \partial_{1} \Theta^{(-M)}_{[x_2, L]} (-M, u_2).
\end{align}
Using \eqref{e:Theta_formula}, we can compute explicitly
\begin{equation}
\partial_{1} \partial_{2} \Theta^{(-M)}_{[x_1, x_2]} (-M, -M) = -2 p''_{x_2 - x_1} (0) = \frac{1}{\sqrt{4\pi}} (x_2 - x_1)^{-\frac{3}{2}},
\end{equation}
which gives
\begin{align}
\MoveEqLeft[7]
\mylim{\eta_1 \searrow 0} \frac{1}{|\eta_1|} \Bigl(\mathbf{Q}_L^{(\eta_1; \star)} - \mathbf{Q}_L^{(0; \star)}\Bigr) (u_1, u_2)\\
&= \frac{1}{\sqrt{4\pi}} (x_2 - x_1)^{-\frac{3}{2}} \cdot \partial_{2} \Theta^{(-M)}_{[-L, x_1]} (u_1, -M) \cdot \partial_{1} \Theta^{(-M)}_{[x_2, L]} (-M, u_2).
\end{align}
As above, uniformity in the variables $u_1, u_2 \in \mathbb{R}$, $(x_1, x_2) \in S$ and $M \in \bar S$ follows readily from the properties of the kernels. This operator is rank one, which finishes the proof of \eqref{eq:Q_0_0} and \eqref{eq:Q_0_0_formula}.

