\Bigl\| \mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +} \Bigr\|_{L^2} \leq C, \qquad\qquad \Bigl\| \mathbf{D}^{(\eta_1; \eta_2)}_{[-L, x], -} \Bigr\|_{L^2} \leq C,
\end{equation}
uniformly over $(x_1, x_2) \in S$, $|x| \leq \beta L$, $M \in \bar S$, and $\eta_1, \eta_2 \in [0, \frac{A}{2}]^2$. Here, $C \geq 0$ is a constant that depends only on $L$ and $\bar L$, the dependence of the functions in \eqref{eqs:D_def} on $x_1$, $x_2$ and $M$ comes through the function $\mathfrak{g}_{\eta_1, \eta_2}$ defined in  \eqref{eq:g_def}, and the constant $\beta > 0$ is from the definition of $\mathsf{J}_{L}$ in \eqref{eq:setJ}.

\begin{equation}\label{eqs:D_bounds}
\Bigl\| \mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +} \Bigr\|_{L^2} \leq C, \qquad\qquad \Bigl\| \mathbf{D}^{(\eta_1; \eta_2)}_{[-L, x], -} \Bigr\|_{L^2} \leq C,
\end{equation}

We start our analysis with the function $\mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +}$, defined in \eqref{eq:D1_def}. First of all, we rewrite the formula to simplify the apparent dependence on $L$. Let $\mathbf{B}$ be Brownian motion of variance two and define $\tau_g$ to be the first hitting time of a function $g : \mathbb{R} \to \mathbb{R}$ from above. That is to say, if the starting time for $\mathbf{B}$ is $x$, then
\begin{equation}\label{eq:tau-def}
\tau_g := \inf\bigl\{\ell \geq x : \mathbf{B}(\ell) \leq g(\ell)\bigr\}.
\end{equation}
Then the transition distribution \eqref{eq:no_hit} may be written as
\begin{equation}
\begin{split}
\MoveEqLeft[6]
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2)\\
&= p_{L - x}(u_2 - u_1) - \mathbb P_{\mathbf{B}(x)=u_1, \mathbf{B}(L) = u_2}\bigl(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L\bigr) \,\cdot\, p_{L - x}(u_2 - u_1),
\end{split}
\end{equation}
where $p_\ell$ is the transition kernel of $\mathbf{B}$, defined in \eqref{eq:heat_kernel}. Using the strong Markov property, we may rewrite the last expression as
\begin{align}
\MoveEqLeft[6]
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2)\\
&= p_{L - x}(u_2 - u_1) - \int_{x}^L \mathbb P_{\mathbf{B}(x) = u_1} \bigl(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathrm{d} s\bigr) \cdot p_{L - s} \bigl(u_2 -\mathfrak{g}_{\eta_1, \eta_2}(s)\bigr).
\label{eq:earlierformula}
\end{align}
Here $\mathbb P_{\mathbf{B}(x) = u_1} (\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}\,)$ is the probability measure on $\mathbb{R}$, generated by the random variable $\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}$ under the initial data that $\mathbf{B}(x) = u_1$. Just looking directly at this integral, it may not be immediately clear that it is finite since if $u_2 \leq -M$, the heat kernel $p_{L - s}$ tends to a Dirac delta function when $s \to L$. Let us briefly explain why the integral is well-defined.  Another way to write the integral is as
\begin{align}
	\mathbb E_{\mathbf{B}(x)=u_1} &\Bigl[p_{L - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(u_2 -\mathfrak{g}_{\eta_1, \eta_2}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}})\bigr) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr]\\
	= &\,\mathbb E_{\mathbf{B}(x)=u_1} \Bigl[p_{L - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(u_2 -\mathfrak{g}_{\eta_1, \eta_2}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}})\bigr) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq x_2 +
	\delta_2}\Bigr] \label{eq:earlierformula1}\\
	&+ \mathbb E_{\mathbf{B}(x)=u_1} \Bigl[p_{L - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} (u_2 + M) \,\cdot\, \1{x_2 +
	\delta_2 < \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr],
\end{align}
where in the last term we used the identity $\mathfrak{g}_{\eta_1, \eta_2}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}) = -M$ almost surely when $x_2 + \delta_2 < \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L$. The first expectation on the right-hand side of \eqref{eq:earlierformula1} is finite, because the heat kernel is bounded. Since $\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}$ is a hitting time of a piecewise constant function, from \cite[Section~2.6]{karatzas1998brownian} we conclude that its probability distribution has a density
$\frac{\mathrm{d}}{\mathrm{d} s} \mathbb P_{\mathbf{B}(x) = u_1} \bigl(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq s\bigr)$,
and, moreover, that on the time interval $s \in (x_2 + \delta_2, L]$ this density is bounded above by a constant which depends on $x_2 + \delta_2$ and $L$ (cf. \eqref{eq:density_stopping_time} and \eqref{eq:density_stopping_time2} for  similar densities). Thus, the last expectation in \eqref{eq:earlierformula1} is bounded by a constant multiple of
$\int_{x_2 + \delta_2}^L \mathrm{d} s\; p_{L - s} (u_2 + M)$, which is finite as desired.

Returning to \eqref{eq:earlierformula}, we claim that this implies that
\begin{equation}\label{eq:Theta_new_formula}
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2) = \Bigl(\mathbf{S}_{0, L - x} - \mathbb{S}_{0, L, [x, L]}^{(\eta_1; \eta_2)}\Bigr) (u_1, u_2),
\end{equation}
where $\mathbf{S}_{t,x}(u,v)$ is defined in  \eqref{eq:fTdef} and
\begin{equation}\label{eq:S_bold}
\mathbb{S}_{t, y, [x, L]}^{(\eta_1; \eta_2)}(u_1, u_2) := \mathbb E_{\mathbf{B}(x)=u_1}\Bigl[ \mathbf{S}_{t, y - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), u_2 \bigr) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr].
\end{equation}
To justify the claim, we observe that $p_\ell(u) = \mathbf{S}_{0,\ell}(u)$ and $\mathbf{S}_{t,x}(u,v) = \mathbf{S}_{t,x}(u - v)$. Using these facts, \eqref{eq:Theta_new_formula} follows readily from \eqref{eq:earlierformula}. The first of these facts, that $p_\ell(u) = \mathbf{S}_{0,\ell}(u)$, follows from \eqref{eq:groupS}.

Using \eqref{eq:Theta_new_formula}, we write  the kernel \eqref{eq:D1_def} in the form
\begin{equation}
\begin{split}
	\mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +}(w) =& \int_{-\infty}^\infty \mathrm{d} v\; \partial_{1} \mathbf{S}_{0, L - x} (-M, v) \cdot \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w)\\
	&- \int_{-\infty}^\infty \mathrm{d} v\; \partial_{1} \mathbb{S}_{0, L, [x, L]}^{(\eta_1; \eta_2)} (-M, v) \cdot \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w).
\end{split}
\label{eq:D1_intermediate}
\end{equation}
Applying the composition identity \eqref{eq:S_properties}, the first integral on the right-hand side of \eqref{eq:D1_intermediate} equals
\begin{equation}\label{eq:D1_intermediate0}
	\partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w).
\end{equation}
Furthermore, fast decay of the functions \eqref{eq:fTdef} at infinity allows us to apply Fubini's theorem and write the second integral in \eqref{eq:D1_intermediate} as
\begin{equation}\label{eq:D1_intermediate1}
\begin{split}
\MoveEqLeft[11]
	\partial_{u} \mathbb E_{\mathbf{B}(x)=u}\Bigl[ \int_{-\infty}^\infty \mathrm{d} v\; \mathbf{S}_{0, L - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), v \bigr)\\
	&\times \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr] \bigg|_{u = -M},
\end{split}
\end{equation}
where we used the definition \eqref{eq:S_bold}. Applying the identity \eqref{eq:S_properties}, the integral inside the expectation can be written as
\begin{equation}
	\bigl(\mathbf{S}_{1/2, - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \Gamma \varrho\bigr) \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), w\bigr).
\end{equation}
Combining this identity with \eqref{eq:D1_intermediate0} and \eqref{eq:D1_intermediate1}, we get from \eqref{eq:D1_intermediate} that
\begin{equation}\label{eq:D1_new_formula}
\mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +}(w) = \partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w) - \partial_{1} \bigl( \mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr) (-M, w).
\end{equation}
Dependence of this expression on $L$ is now more apparent, allowing us to take the limit $L \to \infty$.

Now, we will bound the $L^2$ norm of \eqref{eq:D1_new_formula}. For this, we need to bound the $L^2$ norms of the two terms in \eqref{eq:D1_new_formula}. The reflection operator $\varrho$ in \eqref{eq:D1_new_formula} does not influence the $L^2$ norm and can be omitted. Then Lemma~\ref{lem:S_integral_estimate} yields the  bound on the first term in \eqref{eq:D1_new_formula},
\begin{equation}
\Bigl\| \partial_{1} \bigl(\mathbf{S}_{1/2, - x} \Gamma \varrho\bigr) (-M, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \Bigr\|_{L^2} \leq C_1,
\end{equation}
for all $|x| \leq \beta L$ and $M \in \bar S$, and for some constant $C_1 \geq 0$, depending on $L$ and $\bar L$.

Next, we turn to the second term in \eqref{eq:D1_new_formula}. Using \eqref{eq:S_bold} and integration by parts, we can write
\begin{equation}
\begin{split}
\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} (v, w)
&= \int_x^{L} \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathrm{d} s\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - s} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(s), w\bigr)\\
&= \int_x^{L} \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < s\bigr) \,\cdot\, \partial_s \bigl( \mathbf{S}_{1/2, - s} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(s), w\bigr) \mathrm{d} s\\
&\quad\qquad + \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - L} \Gamma \varrho \bigr) \bigl(-M, w\bigr)\\
&\quad\qquad - \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq x\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - x} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(x), w\bigr),
\end{split}
\label{eq:last_term_formula}
\end{equation}
where we used $\mathfrak{g}_{\eta_1, \eta_2}(L) = M$. As in \eqref{eq:earlierformula}, we use in this formula the probability distribution $\mathbb P_{\mathbf{B}(x)=v} ( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathrm{d} s\,)$ generated by the random variable $\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}$. The integration-by-parts formula holds for any probability distribution (not necessarily absolutely continuous) and can be found in \cite[Theorem~21.67]{Hewitt}. From \eqref{e:Theta_formula}, one can readily conclude that
\begin{align}
\Bigl|\partial_{v}\mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < s\bigr) \big|_{v = -M} \Bigr| &\leq C (s - x)^{-\frac{1}{2}}, \quad \text{for}~s > x,\\
\Bigl|\partial_{v}\mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < x\bigr) \big|_{v = -M} \Bigr| &= 0.
\end{align}
Formula \eqref{eq:fTdef} implies that $\partial_x \mathbf{S}_{t,x}(z) = \mathbf{S}_{t,x}''(z)$, where the derivatives on the right-hand side are taken with respect to $z$. Applying these bounds and identities to \eqref{eq:last_term_formula}, we learn that
\begin{align}
\Bigl|\partial_{1} \bigl(\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr) (-M, w)\Bigr| &\leq C \int_x^{L} (s - x)^{-\frac{1}{2}} \bigl|\bigl( \mathbf{S}_{1/2, - s}'' \Gamma \varrho \bigr) (-M - w) \bigr| \mathrm{d} s \\
&\hspace{2cm} + C (L - x)^{-\frac{1}{2}} \bigl|\bigl( \mathbf{S}_{1/2, -L} \Gamma \varrho \bigr) (-M - w)\bigr|.
\end{align}
Using the triangle inequality for the $L^2$ norm, we obtain
\begin{align}
\Bigl\| \partial_{1} \bigl(\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr)  (-M, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \Bigr\|_{L^2} &\leq C \int_x^{L} (s - x)^{-\frac{1}{2}} \bigl\| \bigl( \mathbf{S}_{1/2, - s}'' \Gamma \varrho \bigr) (-M - \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|_{L^2} \mathrm{d} s \\
&\hspace{1.5cm} + C (L - x)^{-\frac{1}{2}} \bigl\|\bigl( \mathbf{S}_{1/2, -L} \Gamma \varrho \bigr) (-M - \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5})\bigr\|_{L^2}.\label{eq:term2}
\end{align}
In view of Lemma~\ref{lem:S_integral_estimate}, the last term in this expression is bounded by $(L - x)^{-\frac{1}{2}} C_2$.
Since $-L \leq - s \leq L$, the assumptions of Lemma~\ref{lem:S_integral_estimate} are satisfied, and the first term in \eqref{eq:term2} is bounded by
\begin{equation}
C_3 \int_x^{L} (s - x)^{-\frac{1}{2}} \mathrm{d} s =   \frac{1}{2} C_3 (L-x)^{\frac{1}{2}}.
\end{equation}
Combining the derived bounds on \eqref{eq:D1_new_formula}, we obtain the first bound in \eqref{eqs:D_bounds}.
\smallskip

Now, we will prove the second bound in \eqref{eqs:D_bounds}. From definition \eqref{eq:D2_def}, we get
\begin{equation}\label{eq:D-new}
\mathbf{D}^{(\eta_1; \eta_2)}_{[-L, x], -}(w) = \partial_{1} \Bigl(\mathbf{P}_{[-x, L]}^{\uptext{No\! hit}\,(-\bar{\mathfrak{g}}_{\eta_2, \eta_1})} \mathbf{S}_{1/2,-L} \Gamma \varrho \Bigr) (-M, w),
\end{equation}
for a new function $\bar {\mathfrak{g}}_{\eta_2, \eta_1}(y) := M - \varepsilon_2 \cdot \1{y \in (-x_2 - \delta_2, -x_2]} - \varepsilon_1 \cdot \1{y \in (-x_1 - \delta_1, -x_1]}$. The formula \eqref{eq:D-new} is the same as \eqref{eq:D1_def}, but for this new function $\bar {\mathfrak{g}}_{\eta_2, \eta_1}$. Then the second bound in \eqref{eqs:D_bounds} follows from the first one.

\begin{equation}\label{eq:tau-def}
\tau_g := \inf\bigl\{\ell \geq x : \mathbf{B}(\ell) \leq g(\ell)\bigr\}.
\end{equation}

\begin{equation}
\begin{split}
\MoveEqLeft[6]
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2)\\
&= p_{L - x}(u_2 - u_1) - \mathbb P_{\mathbf{B}(x)=u_1, \mathbf{B}(L) = u_2}\bigl(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L\bigr) \,\cdot\, p_{L - x}(u_2 - u_1),
\end{split}
\end{equation}

\begin{align}
\MoveEqLeft[6]
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2)\\
&= p_{L - x}(u_2 - u_1) - \int_{x}^L \mathbb P_{\mathbf{B}(x) = u_1} \bigl(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathrm{d} s\bigr) \cdot p_{L - s} \bigl(u_2 -\mathfrak{g}_{\eta_1, \eta_2}(s)\bigr).
\label{eq:earlierformula}
\end{align}

\begin{equation}\label{eq:Theta_new_formula}
\mathbf{P}_{[x, L]}^{\uptext{No\! hit}\,(-\mathfrak{g}_{\eta_1, \eta_2})}(u_1, u_2) = \Bigl(\mathbf{S}_{0, L - x} - \mathbb{S}_{0, L, [x, L]}^{(\eta_1; \eta_2)}\Bigr) (u_1, u_2),
\end{equation}

\begin{equation}\label{eq:S_bold}
\mathbb{S}_{t, y, [x, L]}^{(\eta_1; \eta_2)}(u_1, u_2) := \mathbb E_{\mathbf{B}(x)=u_1}\Bigl[ \mathbf{S}_{t, y - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), u_2 \bigr) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr].
\end{equation}

\begin{equation}
\begin{split}
	\mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +}(w) =& \int_{-\infty}^\infty \mathrm{d} v\; \partial_{1} \mathbf{S}_{0, L - x} (-M, v) \cdot \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w)\\
	&- \int_{-\infty}^\infty \mathrm{d} v\; \partial_{1} \mathbb{S}_{0, L, [x, L]}^{(\eta_1; \eta_2)} (-M, v) \cdot \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w).
\end{split}
\label{eq:D1_intermediate}
\end{equation}

\begin{equation}\label{eq:D1_intermediate0}
	\partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w).
\end{equation}

\begin{equation}\label{eq:D1_intermediate1}
\begin{split}
\MoveEqLeft[11]
	\partial_{u} \mathbb E_{\mathbf{B}(x)=u}\Bigl[ \int_{-\infty}^\infty \mathrm{d} v\; \mathbf{S}_{0, L - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), v \bigr)\\
	&\times \bigl(\mathbf{S}_{1/2,-L} \Gamma \varrho\bigr) (v, w) \,\cdot\, \1{\tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L}\Bigr] \bigg|_{u = -M},
\end{split}
\end{equation}

\begin{equation}
	\bigl(\mathbf{S}_{1/2, - \tau_{-\mathfrak{g}_{\eta_1, \eta_2}}} \Gamma \varrho\bigr) \bigl(\mathbf{B}(\tau_{-\mathfrak{g}_{\eta_1, \eta_2}}), w\bigr).
\end{equation}

\begin{equation}\label{eq:D1_new_formula}
\mathbf{D}^{(\eta_1; \eta_2)}_{[x, L], +}(w) = \partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w) - \partial_{1} \bigl( \mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr) (-M, w).
\end{equation}

\begin{equation}
\Bigl\| \partial_{1} \bigl(\mathbf{S}_{1/2, - x} \Gamma \varrho\bigr) (-M, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \Bigr\|_{L^2} \leq C_1,
\end{equation}

\begin{equation}
\begin{split}
\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} (v, w)
&= \int_x^{L} \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \in \mathrm{d} s\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - s} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(s), w\bigr)\\
&= \int_x^{L} \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < s\bigr) \,\cdot\, \partial_s \bigl( \mathbf{S}_{1/2, - s} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(s), w\bigr) \mathrm{d} s\\
&\quad\qquad + \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq L\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - L} \Gamma \varrho \bigr) \bigl(-M, w\bigr)\\
&\quad\qquad - \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} \leq x\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - x} \Gamma \varrho \bigr) \bigl(-\mathfrak{g}_{\eta_1, \eta_2}(x), w\bigr),
\end{split}
\label{eq:last_term_formula}
\end{equation}

\begin{align}
\Bigl|\partial_{v}\mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < s\bigr) \big|_{v = -M} \Bigr| &\leq C (s - x)^{-\frac{1}{2}}, \quad \text{for}~s > x,\\
\Bigl|\partial_{v}\mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-\mathfrak{g}_{\eta_1, \eta_2}} < x\bigr) \big|_{v = -M} \Bigr| &= 0.
\end{align}

\begin{align}
\Bigl|\partial_{1} \bigl(\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr) (-M, w)\Bigr| &\leq C \int_x^{L} (s - x)^{-\frac{1}{2}} \bigl|\bigl( \mathbf{S}_{1/2, - s}'' \Gamma \varrho \bigr) (-M - w) \bigr| \mathrm{d} s \\
&\hspace{2cm} + C (L - x)^{-\frac{1}{2}} \bigl|\bigl( \mathbf{S}_{1/2, -L} \Gamma \varrho \bigr) (-M - w)\bigr|.
\end{align}

\begin{align}
\Bigl\| \partial_{1} \bigl(\mathbb{S}_{1/2, 0, [x, L]}^{(\eta_1; \eta_2)} \Gamma \varrho\bigr)  (-M, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \Bigr\|_{L^2} &\leq C \int_x^{L} (s - x)^{-\frac{1}{2}} \bigl\| \bigl( \mathbf{S}_{1/2, - s}'' \Gamma \varrho \bigr) (-M - \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|_{L^2} \mathrm{d} s \\
&\hspace{1.5cm} + C (L - x)^{-\frac{1}{2}} \bigl\|\bigl( \mathbf{S}_{1/2, -L} \Gamma \varrho \bigr) (-M - \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5})\bigr\|_{L^2}.\label{eq:term2}
\end{align}

\begin{equation}
