&\quad- \det \Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{G}_L^{(0)} - \mathbf{A}_L^{(\star; 0)}\Bigr) \Bigr) + \det \Bigl(I-\mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2}\mathbf{G}_L^{(0)}\Bigr).
\end{align}

\begin{equation}
\begin{split}
\mathcal{F}_{1, M, L}(x_1, x_2) &= \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}_L^{(0; 0)} - \mathbf{A}_L^{(0; \star)} - \mathbf{A}_L^{(\star; 0)} + \mathbf{A}_L^{(\star; \star)}\Bigr) \Bigr) \\
&\quad - \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}_L^{(0; 0)} - \mathbf{A}_L^{(0; \star)}\Bigr) \Bigr)\\
&\quad - \det \Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}_L^{(0; 0)} - \mathbf{A}_L^{(\star; 0)}\Bigr) \Bigr) + \det \Bigl(I-\mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2}\mathbf{R}_L^{(0; 0)}\Bigr).
\end{split}
\label{e:final}
\end{equation}

\begin{equation}\label{eq:R-limit}
\mathbf{R} := \lim_{L \to \infty} \mathbf{R}_L^{(0; 0)} = \mathbf{K}^{\uptext{epi}(-M)}_{1/2},
\end{equation}

\begin{equation}
\mathbf{D}^{(0; 0)}_{[x, L], +}(w) = \partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w) - \partial_{1} \bigl( \mathbb{S}_{1/2, 0, [x, L]}^{(0; 0)} \Gamma \varrho\bigr) (-M, w),
\end{equation}

\begin{equation}
\mathbb{S}_{1/2, 0, [x, L]}^{(0; 0)} (v, w) = \int_x^{L} \mathbb P_{\mathbf{B}(x)=v} \bigl( \tau_{-M} \in \mathrm{d} s\bigr) \,\cdot\, \bigl( \mathbf{S}_{1/2, - s} \Gamma \varrho \bigr) \bigl(-M, w\bigr),
\end{equation}

\begin{equation}
\lim_{L \to \infty} \partial_{1} \mathbb{S}_{1/2, 0, [x, L]}^{(0; 0)} (v, w) = - \partial_{1} \bigl( \mathbf{S}_{1/2, - x} \Gamma \varrho \bigr) \bigl(-2M - v, w\bigr),
\end{equation}

\begin{equation}\label{eq:D-limit}
\mathbf{D}_{x}(w) := \lim_{L \to \infty} \mathbf{D}^{(0; 0)}_{[x, L], +}(w) = 2 \partial_{1} \bigl(\mathbf{S}_{1/2,-x} \Gamma \varrho\bigr) (-M, w).
\end{equation}

\begin{equation}\label{eq:A-limits}
\begin{aligned}
\mathbf{A}^{(0; \star)}(u_1, u_2) := \lim_{L \to \infty} \mathbf{A}_L^{(0; \star)}(u_1, u_2) &= \mathbf{D}_{-x_2}(u_1) \,\cdot\, \mathbf{D}_{x_2}(u_2), \\
\mathbf{A}^{(\star; 0)}(u_1, u_2) := \lim_{L \to \infty} \mathbf{A}_L^{(\star; 0)}(u_1, u_2) &= \mathbf{D}_{-x_1}(u_1) \,\cdot\, \mathbf{D}_{x_1}(u_2), \\
\mathbf{A}^{(\star; \star)}(u_1, u_2) := \lim_{L \to \infty} \mathbf{A}_L^{(\star; \star)}(u_1, u_2) &= \frac{1}{\sqrt{4\pi}} (x_2 - x_1)^{-\frac{3}{2}} \, \cdot\, \mathbf{D}_{-x_1}(u_1) \,\cdot\, \mathbf{D}_{x_2}(u_2). 
\end{aligned}
\end{equation}

\begin{equation}
\begin{split}
\mathcal{F}_{1, M}(x_1, x_2) &= \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R} - \mathbf{A}^{(0; \star)} - \mathbf{A}^{(\star; 0)} + \mathbf{A}^{(\star; \star)}\Bigr) \Bigr) \\
&\quad - \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R} - \mathbf{A}^{(0; \star)}\Bigr) \Bigr)\\
&\quad - \det \Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R} - \mathbf{A}^{(\star; 0)}\Bigr) \Bigr) + \det \Bigl(I-\mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2}\mathbf{R}\Bigr).
\end{split}
\label{e:final-infinity}
\end{equation}

\begin{equation}
\mathcal{F}_{t, M, L}^{(\eta_1; \eta_2)}(x_1, x_2) = \mathcal{F}_{1, t^{-1/3} M, t^{-2/3} L}^{(\eta^{(t)}_1, \eta^{(t)}_2)} \bigl(t^{-\frac{2}{3}} x_1, t^{-\frac{2}{3}} x_2\bigr),
\end{equation}

\begin{align}
\mathcal{F}_{t, M, L}(x_1, x_2) &= t^{-2} \mylim{\eta_1 \searrow 0}\, \mylim{\eta_2 \searrow 0} \frac{1}{|\eta^{(t)}_1| |\eta^{(t)}_2|} \mathcal{F}_{1, t^{-1/3} M, t^{-2/3} L}^{(\eta^{(t)}_1, \eta^{(t)}_2)} \bigl(t^{-\frac{2}{3}} x_1, t^{-\frac{2}{3}} x_2\bigr) \\
&= t^{-2} \mathcal{F}_{1, t^{-1/3} M, t^{-2/3} L} \bigl(t^{-\frac{2}{3}} x_1, t^{-\frac{2}{3}} x_2\bigr),
\end{align}

\begin{equation}
\mathcal{F}_{1, M, L} = \mathcal{F}^{(1)}_{1, M, L} + \mathcal{F}^{(2)}_{1, M, L} + \mathcal{F}^{(3)}_{1, M, L},
\end{equation}

\begin{align}
\mathcal{F}^{(1)}_{1, M, L}(x_1, x_2) :=& \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}^{(0; 0)}_L - \mathbf{A}^{(0; \star)}_L - \mathbf{A}^{(\star; 0)}_L + \mathbf{A}^{(\star; \star)}_L\Bigr) \Bigr) \\
&- \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}^{(0; 0)}_L - \mathbf{A}^{(0; \star)}_L - \mathbf{A}^{(\star; 0)}_L \Bigr) \Bigr),\label{eq:P1_def}\\

\mathcal{F}^{(2)}_{1, M, L}(x_1, x_2) :=& \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}^{(0; 0)}_L - \mathbf{A}^{(0; \star)}_L - \mathbf{A}^{(\star; 0)}_L\Bigr) \Bigr) \\
& - \det\Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}^{(0; 0)}_L - \mathbf{A}^{(0; \star)}_L \Bigr) \Bigr)\label{eq:P2_def}\\

\mathcal{F}^{(3)}_{1, M, L}(x_1, x_2) :=& \det \Bigl(I-\mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \mathbf{R}^{(0; 0)}_L\Bigr) \\
&- \det \Bigl(I- \mathbf{K}^{\uptext{hypo}(\mathfrak{h}_0)}_{1/2} \Bigl(\mathbf{R}^{(0; 0)}_L - \mathbf{A}^{(\star; 0)}_L\Bigr) \Bigr). \label{eq:P3_def}
\end{align}

\begin{align}
\mathcal{F}^{(1)}_{1, M, L}(x_1, x_2) &\leq C |x_2 - x_1|^{-\frac{3}{2}},\label{eq:P1_bound}\\
\mathcal{F}^{(2)}_{1, M, L}(x_1, x_2) \leq C,& \qquad \mathcal{F}^{(3)}_{1, M, L}(x_1, x_2) \leq C,\label{eq:P2_bound}
\end{align}

\begin{align}\label{eq:P1_bound_intermediate}
\mathcal{F}^{(1)}_{1, M, L}(x_1, x_2) \leq C_2 \bigl\| \mathbf{A}_L^{(\star; \star)} \bigr\|_1,
\end{align}

\begin{equation}\label{eq:P2_bound_intermediate1}
\mathcal{F}^{(2)}_{1, M, L}(x_1, x_2) \leq C_4 \bigl\| \mathbf{A}^{(\star; 0)}_L \bigr\|_1, \qquad \mathcal{F}^{(3)}_{1, M, L}(x_1, x_2) \leq C_4 \bigl\| \mathbf{A}^{(0; \star)}_L \bigr\|_1.
\end{equation}

We may write the probability on the left-hand side of \eqref{eq:q_def} for the cut-off as
\begin{align}\label{eq:q_equality}
\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon}\Bigr) = \sum_{M \in \varepsilon \mathbb{Z}} \mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon},\, \mathrm{Max}(\mathfrak{h}^L_t) \in (M-\varepsilon, M]\Bigr).
\end{align}
Let us define the $\varepsilon$-fattening of $\mathsf{J}_{\bar L}$ by $\mathsf{J}_{\bar L}^{\varepsilon} := \bigcup_{x \in \mathsf{J}_{\bar L}} [x - \varepsilon, x + \varepsilon]$. From the definition of the set $\TP{A, \bar L}^{\varepsilon}$, we conclude that, if $\mathsf{J}_{\bar L^{1/2}}^{\varepsilon} \cap (M-\varepsilon, M] = \varnothing$, then the term indexed by $M$ in the sum \eqref{eq:q_equality} vanishes. When this term does not vanish, we can estimate it by
\begin{align}
&\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon},\, \mathrm{Max}(\mathfrak{h}^L_t) \in (M-\varepsilon, M]\Bigr) \\
&\quad \leq \mathbb P_{\mathfrak{h}_0} \Bigl(\exists\, x_1, x_2 \in \mathsf{J}_{L} : x_2 - x_1 \geq A,\; \mathfrak{h}_{t}(x_i) > M - 2 \varepsilon,\; \mathfrak{h}_{t}(y) \leq M ~\text{for}~ y \in [- L,  L]\Bigr).
\end{align}
For $0 < \delta \leq A$, denote $\overline \eta = (2 \varepsilon, \delta)$, and let $A_\delta$ be the largest value in $\delta \mathbb{Z}$ such that $0 < A_\delta \leq A$. Then, using the function $\mathcal{F}_{t, M, L}^{(\eta_1; \eta_2)}(x_1, x_2)$, defined in \eqref{eq:density}, we have the upper bound
\begin{equation}\label{eq:bound_by_sums}
\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon}\Bigr) \leq \sum_{\substack{x_1, x_2 \in (\delta \mathbb{Z}) \cap \mathsf{J}_{ L}^{\delta} \\ x_2 - x_1 \geq A_\delta}} \sum_{M \in (\varepsilon \mathbb{Z}) \cap \mathsf{J}_{\bar L^{1/2}}^{\varepsilon}} \mathcal{F}^{(\overline\eta; \overline\eta)}_{t, M, L}(x_1, x_2).
\end{equation}
For $0 < \delta_1 \leq \delta_2$ and $0 < \varepsilon_1 \leq \varepsilon_2$, let us set $\overline \eta_1 = (2 \varepsilon_1, \delta_1)$ and $\overline \eta_2 = (2 \varepsilon_2, \delta_2)$. Moreover, we define
\begin{equation}
	\mathcal{I}^{(\overline\eta_1; \overline\eta_2)} := \sum_{\substack{x_1, x_2 \in (\delta_1 \mathbb{Z}) \cap \mathsf{J}_{ L}^{\delta_1} \\ x_2 - x_1 \geq A_{\delta_1}}} \sum_{M \in (\varepsilon_1 \mathbb{Z}) \cap \mathsf{J}_{\bar L^{1/2}}^{\varepsilon_1}} \mathcal{F}^{(\overline\eta_1; \overline\eta_2)}_{t, M, L}(x_1, x_2),
\end{equation}
where we prefer to suppress dependence on the variables $t$, $A$, etc. Then \eqref{eq:bound_by_sums} reads as
\begin{equation}
\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon}\Bigr) \leq \mathcal{I}^{(\overline\eta; \overline\eta)}.
\end{equation}

From \eqref{e:densities1}, we conclude that for every fixed $\bar \eta_1 > 0$ the following limit holds:
\begin{equation}\label{eq:limit_to_integrals1}
\mylim{\bar \eta_2 \searrow 0} \frac{1}{|\bar \eta_2|} \mathcal{I}^{(\bar \eta_1; \bar \eta_2)} = \sum_{\substack{x_1, x_2 \in (\delta_1 \mathbb{Z}) \cap \mathsf{J}_{ L}^{\delta_1} \\ x_2 - x_1 \geq A_{\delta_1}}} \sum_{M \in (\varepsilon_1 \mathbb{Z}) \cap \mathsf{J}_{\bar L^{1/2}}^{\varepsilon_1}} \mathcal{F}^{(\overline\eta_1; \star)}_{t, M, L}(x_1, x_2)=:\mathcal{I}^{(\bar \eta_1; \star)}.
\end{equation}
Since the limit \eqref{e:densities1} holds uniformly over $\eta_1$ and since the function $\mathcal{F}^{(\overline\eta; \overline\eta)}_{t, M, L}(x_1, x_2)$ is positive, we conclude that there exist constants $\chi_1 > 0$ and $C_1 > 0$, independent of $\bar \eta_1$ and $\bar \eta_2$, such that
\begin{equation}\label{eq:I1_bound}
\mathcal{I}^{(\bar \eta_1; \bar \eta_2)} \leq C_1 |\bar \eta_2|\, \mathcal{I}^{(\bar \eta_1; \star)},
\end{equation}
for all $\bar \eta_1, \bar \eta_2 \in (0, \chi_1]^2$ and $\bar \eta_2 \in \mathsf{Dom}$ (this domain is defined in \eqref{eq:Dom}). Now we claim that
\begin{equation}\label{eq:limit_to_integrals2}
\mylim{\bar \eta_1 \searrow 0} \varepsilon_1^{-1} |\bar \eta_1| \mathcal{I}^{(\bar \eta_1; \star)} = C_2 \int_{-\beta L}^{\beta L - A} \mathrm{d} x_1 \int_{x_1 + A}^{\beta L} \mathrm{d} x_2 \int_{-\beta \sqrt{\bar L}}^{\beta \sqrt{\bar L}} \mathrm{d} M\; \mathcal{F}_{t, M, L}(x_1, x_2)=:\mathcal{I},
\end{equation}
for a constant $C_2 > 0$ which we define later, and where the constant $\beta$ arises from the definition of $\mathsf{J}_{ L}$. We note that continuity of the function $\mathcal{F}_{t, M, L}$, proved in Proposition~\ref{prop:densities}, guarantees that the latter triple integral is well-defined. We postpone our proof of this limit for the moment, and show how it implies the bound \eqref{eq:q_def}.

From \eqref{eq:limit_to_integrals2}, we conclude that there exist constants $\chi_3 > 0$ and $C_3 > 0$ such that
\begin{equation}\label{eq:I2_bound}
\mathcal{I}^{(\bar \eta_1; \star)} \leq C_3 \frac{\varepsilon_1}{|\bar \eta_1|} \mathcal{I},
\end{equation}
for all $\bar \eta_1 \in (0,\chi_3]^2 \cap \mathsf{Dom}$. Hence, from  \eqref{eq:bound_by_sums}, and from the two bounds \eqref{eq:I1_bound} and \eqref{eq:I2_bound}, we get
\begin{equation}\label{eq:C4eCI}
	\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon}\Bigr) \leq C_4 \varepsilon \mathcal{I}

\end{equation}
where $C_4 = C_1 C_2 C_3$. Using the scaling property \eqref{e:densities_scale}, changing the variables of integration, denoting $\bar L_t := t^{-2/3} \bar L$, $L_t := t^{-2/3} L$ and $A_t := t^{-2/3} A$, and using the bound in \eqref{eq:P_bound} on $\mathcal{F}_{1, M, L_t} ( x_1, x_2)$, we may write the preceding expression explicitly as
\begin{equation}
C_4 \varepsilon \mathcal{I} = C_5 \varepsilon t^{-\frac{1}{3}} \int_{-\beta  L_t}^{\beta L_t - A_t} \mathrm{d} x_1 \int_{x_1 + A_t}^{\beta  L_t} \mathrm{d} x_2 \int_{-\beta \sqrt{\bar L_t}}^{\beta \sqrt{\bar L_t}} \mathrm{d} M\; |x_2 - x_1|^{-\frac{3}{2}}
\end{equation}
where the constants $C_5$ and $c$ depend on $L_{T_0}$, $\bar L_{T_0}$ and $\alpha$ (the constant $\alpha$ arises from the upper bound on the initial data $\mathfrak{h}_0$). In Theorem \ref{thm:densities2-intro}, we have assumed that $t\in [T_0,T]$. For this range of~$t$ and given the condition that $x_2-x_1\geq A_t\leq A_{T_0}$ from the integral above, we can bound above $\exp\big\{c |x_2 - x_1|^{-\frac{3}{2}}\big\} \leq \exp \big\{ c A_{T_0}^{-3/2} \big\}$. Inserting this bound and evaluating the integrals yields another constant depending just on $\beta, T_0, L, \bar{L}$ and $A$. Thus we have shown that
$C_4 \varepsilon \mathcal{I} \leq C_6 \varepsilon t^{-1 / 3}$. In light of \eqref{eq:C4eCI}, this yields~\eqref{eq:q_def} and completes the proof.






\smallskip

All that remains is to prove the limit \eqref{eq:limit_to_integrals2}. For this, let us define the finite sets
\begin{equation}
S_\delta := \left\{(x_1, x_2) : x_i \in (\delta \mathbb{Z}) \cap \mathsf{J}_{ L}^{\delta},\; x_2 - x_1 \geq A_\delta\right\}, \qquad \bar S_\varepsilon := (\varepsilon \mathbb{Z}) \cap \mathsf{J}_{\bar L^{1/2}}^{\varepsilon},
\end{equation}
 over which the summation in \eqref{eq:bound_by_sums} is performed. Recalling that $\overline \eta_1 = (2 \varepsilon_1, \delta_1)$, we may write
\begin{align}
\varepsilon_1^{-1} |\bar \eta_1| \mathcal{I}^{(\bar \eta_1; \star)} - \mathcal{I} &= \varepsilon_1^{-1} |\bar \eta_1|^2 \sum_{\substack{(x_1, x_2) \in S_{\delta_1} \\ M \in \bar S_{\varepsilon_1}}} \left( \frac{1}{|\overline \eta_1|} \mathcal{F}^{(\overline\eta_1; \star)}_{t, M, L}(x_1, x_2) - \mathcal{F}_{t, M, L}(x_1, x_2) \right)\\
&\hspace{3cm} + \biggl( \varepsilon_1^{-1} |\bar \eta_1|^2 \sum_{\substack{(x_1, x_2) \in S_{\delta_1} \\ M \in \bar S_{\varepsilon_1}}} \mathcal{F}_{t, M, L}(x_1, x_2) - \mathcal{I} \biggr).\label{eq:limit_to_integrals_proof}
\end{align}
Call the first term on the right-hand side $\mathcal{I}_1$ and the second one $\mathcal{I}_2$.
The cardinalities $|S_{\delta_1}|$ and $|\bar S_{\varepsilon_1}|$ are respectively proportional to $\delta_1^{-2}$ and $\varepsilon_1^{-1}$, and we can define the finite constants $\lim_{\delta_1 \searrow 0} \delta_1^2 |S_{\delta_1}| = C_7$ and $\lim_{\varepsilon_1 \searrow 0} \varepsilon_1 |\bar{S}_{\varepsilon_1}| = C_8$, where $C_7$ depends on $L$, $A$ and $\beta$, and $C_8$ depends on $\bar L$ and $\beta$. Moreover, we define the sets
\begin{equation}
S := \bigcap_{\delta_1 > 0} S_{\delta_1} = \bigl\{(x_1, x_2) : x_i \in \mathsf{J}_{L},\; x_2 - x_1 \geq A\bigr\}, \qquad \bar S := \bigcap_{\varepsilon_1 > 0} \bar{S}_{\varepsilon_1} = \mathsf{J}_{\bar L^{1/2}}.
\end{equation}
Proposition~\ref{prop:densities} implies continuity of the function $\mathcal{F}_{t, M, L}(x_1, x_2)$ for $(x_1, x_2) \in S$ and $M \in \bar S$. Hence, if we take the constant $C_2 = \lim_{\varepsilon_1, \delta_1 \searrow 0} \varepsilon_1^{-1} |\bar \eta_1|^2 |S_{\delta_1}| |\bar{S}_{\varepsilon_1}| = 4 C_7 C_8$ in \eqref{eq:limit_to_integrals2}, then $|\mathcal{I}_2|\to 0$ in the limit $\varepsilon_1, \delta_1 \searrow 0$, in view of the definition of a multiple integral as a limit of Riemann sums.

To deal with the other term, observe that
\begin{equation}\label{eq:limit_to_integrals_proof2}
|\mathcal{I}_2|\leq \varepsilon_1^{-1} |\bar \eta_1|^2 |S_{\delta_1}| |\bar S_{\varepsilon_1}| \sup_{\substack{(x_1, x_2) \in S_{\delta_1} \\ M \in \bar S_{\varepsilon_1}}} \left| \frac{1}{|\overline \eta_1|} \mathcal{F}^{(\overline\eta_1; \star)}_{t, M, L}(x_1, x_2) - \mathcal{F}_{t, M, L}(x_1, x_2) \right|.
\end{equation}
The multiplier $\varepsilon_1^{-1} |\bar \eta_1|^2 |S_{\delta_1}| |\bar S_{\varepsilon_1}|$ converges to $C_2$ as $\varepsilon_1, \delta_1 \searrow 0$, and Proposition~\ref{prop:densities} implies that the expression \eqref{eq:limit_to_integrals_proof2} vanishes as $\overline \eta_1 \searrow 0$ along the domain $\mathsf{Dom}$. This finishes the proof of \eqref{eq:limit_to_integrals2}.

\begin{align}\label{eq:q_equality}
\mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon}\Bigr) = \sum_{M \in \varepsilon \mathbb{Z}} \mathbb P_{\mathfrak{h}_0} \Bigl(\mathfrak{h}^L_t \in \TP{A, \bar L}^{\varepsilon},\, \mathrm{Max}(\mathfrak{h}^L_t) \in (M-\varepsilon, M]\Bigr).
\end{align}

\begin{align}
