\thmtitle{Hausdorff measure and dimension} 
 Let $S \subset \mathbb{R}$ and $0 \leq \alpha < \infty$.
\begin{enumerate}
\item For $0 < \delta \leq \infty$, we define the \emph{$\delta$-approximate packing pre-measure}
\begin{equation}\label{eq:pre-measure}
\mathcal{H}^\alpha_\delta(S) := \inf \left\{ \sum_{i = 1}^\infty \mathrm{diam} (J_i)^\alpha : S \subset \bigcup_{i = 1}^\infty J_i,\; \mathrm{diam} (J_i) < \delta \right\},
\end{equation}
where the infimum is taken over all countable covers of $S$ by sets $J_i \subset \mathbb{R}$ with $\mathrm{diam}(J_i) < \delta$, and where $\mathrm{diam}(J_i)$ is the supremum of all distances between points in $J_i$.
\item We define the \emph{$\alpha$-dimensional Hausdorff measure}
\begin{equation}\label{eq:measure}
\mathcal{H}^\alpha(S) := \lim_{\delta \to 0} \mathcal{H}^\alpha_\delta(S) = \sup_{\delta > 0} \mathcal{H}^\alpha_\delta(S).
\end{equation}
We note that $\mathcal{H}^\alpha(S)$ is well-defined (although it can be infinite), because $\mathcal{H}^\alpha_\delta(S)$ monotonically increases as $\delta \searrow 0$.
\item The \emph{Hausdorff dimension} of $S$ is defined by the following equivalent formulas:
\begin{align}\label{eq:Hausdorff_dim}
\dim(S) &:= \sup \{\alpha \geq 0 : \mathcal{H}^\alpha(S) > 0\} = \sup \{\alpha \geq 0 : \mathcal{H}^\alpha(S) = \infty\} \\
&= \inf \{\alpha \geq 0 : \mathcal{H}^\alpha(S) < \infty\} = \inf \{\alpha \geq 0 : \mathcal{H}^\alpha(S) = 0\}.
\end{align}
Note that $0 \leq \dim(S) \leq 1$ for any $S \subset \mathbb{R}$.
\end{enumerate}

\begin{equation}\label{eq:pre-measure}
\mathcal{H}^\alpha_\delta(S) := \inf \left\{ \sum_{i = 1}^\infty \mathrm{diam} (J_i)^\alpha : S \subset \bigcup_{i = 1}^\infty J_i,\; \mathrm{diam} (J_i) < \delta \right\},
\end{equation}

\begin{equation}\label{eq:measure}
\mathcal{H}^\alpha(S) := \lim_{\delta \to 0} \mathcal{H}^\alpha_\delta(S) = \sup_{\delta > 0} \mathcal{H}^\alpha_\delta(S).
\end{equation}

\begin{align}\label{eq:Hausdorff_dim}
\dim(S) &:= \sup \{\alpha \geq 0 : \mathcal{H}^\alpha(S) > 0\} = \sup \{\alpha \geq 0 : \mathcal{H}^\alpha(S) = \infty\} \\
&= \inf \{\alpha \geq 0 : \mathcal{H}^\alpha(S) < \infty\} = \inf \{\alpha \geq 0 : \mathcal{H}^\alpha(S) = 0\}.
\end{align}

\label{rem:dimension}
