\end{equation}

\begin{equation}
\bigl| \det (I + A + B)_{\mathcal{H}} - \det (I + A)_{\mathcal{H}} \bigr| \leq \| (I+A)^{-1} \|_1 \| B\|_1 \bigl|\det(I + A)_{\mathcal{H}}\bigr|, \label{eq:det_bound_trace}
\end{equation}

For any trace class operators $A$ and $B$, the following bounds hold \cite[Theorem~3.4]{Simon}:
\begin{equation}\label{eq:det_bound}
\bigl| \det (I + A)_{\mathcal{H}} - \det (I + B)_{\mathcal{H}} \bigr| \leq \| A - B\|_1 e^{\| A\|_1 + \|B\|_1 + 1} \leq \| A - B\|_1 e^{\| A - B\|_1 + 2 \|B\|_1 + 1}.
\end{equation}

\begin{equation}\label{eq:det_bound}
\bigl| \det (I + A)_{\mathcal{H}} - \det (I + B)_{\mathcal{H}} \bigr| \leq \| A - B\|_1 e^{\| A\|_1 + \|B\|_1 + 1} \leq \| A - B\|_1 e^{\| A - B\|_1 + 2 \|B\|_1 + 1}.
\end{equation}

\label{lem:S_bound}
For any integer $n \geq 0$, there exists a constant $C > 0$, such that
\begin{equation}\label{eq:S_bound}
\bigl|\mathbf{S}^{(n)}_{1,x}(z)\bigr| \leq C e^{F(x, z)},
\end{equation}
where $F(x, z) := -\tfrac{1}{3} x^3 + x y - \tfrac{2}{3} (y \vee 0)^{3 / 2}$ with $y = x^2 - z$, and where $\mathbf{S}^{(n)}_{1,x}(z)$ denotes the $n^{\text{th}}$ derivative with respect to $z$.

\begin{equation}\label{eq:S_bound}
\bigl|\mathbf{S}^{(n)}_{1,x}(z)\bigr| \leq C e^{F(x, z)},
\end{equation}

We first derive a bound on the Airy function and its derivatives. The Airy function can be written in terms of the Bessel functions as
\begin{equation}\label{eq:Airy_function}
\uptext{Ai}(z) = \frac{1}{\pi} \sqrt{\frac{z}{3}} K_{1/3} (\zeta), \qquad \uptext{Ai}(-z) = \frac{\sqrt{z}}{3} \bigl(J_{-1/3} (\zeta) + J_{1/3} (\zeta) \bigr),
\end{equation}
where $z \geq 0$; $\zeta = \frac{2}{3} z^{\frac{3}{2}}$; $J$ is a Bessel function of the first kind; and $K$ is a modified Bessel function of the second kind \cite[Section~2.2.4]{AiryBook}. Then, from \cite[Eq.~10.29.5]{NIST:DLMF}, we have
\begin{equation}\label{eq:K_recursion}
K^{(n)}_{\nu}(z) = 2^{-n} \sum_{k = 0}^n (-1)^k \binom{n}{k} K_{\nu - n + 2 k}(z).
\end{equation}
Moreover, the function $|K_\nu(z)|$ is bounded by a constant multiple of $e^{- z}$ for $z \geq 0$, where the constant depends on $\nu$ (see \cite[Eq.~10.25.3]{NIST:DLMF}). To be more precise, we have the bound $|K_\nu(z)| \leq C z^{-1/2} e^{- z}$ for large $z \geq 0$. However, the slowly decaying factor $z^{-1/2}$ does not play any role in our analysis. Then, from \eqref{eq:Airy_function} and \eqref{eq:K_recursion}, we obtain
\begin{equation}\label{eq:Airy_bound1}
\bigl|\uptext{Ai}^{(n)}(z)\bigr| \leq C(n) e^{- \frac{2}{3} z^{3/2}},
\end{equation}
for $n \geq 0$ and $z \geq 0$.

Now, we will bound the Airy function $\uptext{Ai}(-z)$ for $z > 0$. Equation 10.6.7 in \cite{NIST:DLMF} implies that the functions $J$ satisfy relation \eqref{eq:K_recursion}. Moreover, from \cite[Eq.~10.7.8]{NIST:DLMF}, we readily conclude that $|J_\nu(z)|$ is bounded by a constant depending on $\nu$. A slightly stronger bound holds for large values of $z$: $|J_\nu(z)| \leq C z^{-1/2}$. As for the function $K_\nu$ we will ignore this slow decay. Combining \eqref{eq:Airy_function} with these properties of the functions $J$, we obtain
\begin{equation}\label{eq:Airy_bound2}
\bigl|\uptext{Ai}^{(n)}(-z)\bigr| \leq C(n),
\end{equation}
for $n \geq 0$ and $z \geq 0$.

From \eqref{eq:Airy_bound1} and \eqref{eq:Airy_bound2}, we conclude that $\bigl|\uptext{Ai}^{(n)}(z)\bigr| \leq C(n) e^{- \frac{2}{3} (z \vee 0)^{3/2}}$. Applying this bound to \eqref{eq:fTdef}, we arrive at \eqref{eq:S_bound}.

\begin{equation}\label{eq:Airy_function}
\uptext{Ai}(z) = \frac{1}{\pi} \sqrt{\frac{z}{3}} K_{1/3} (\zeta), \qquad \uptext{Ai}(-z) = \frac{\sqrt{z}}{3} \bigl(J_{-1/3} (\zeta) + J_{1/3} (\zeta) \bigr),
\end{equation}

\begin{equation}\label{eq:K_recursion}
K^{(n)}_{\nu}(z) = 2^{-n} \sum_{k = 0}^n (-1)^k \binom{n}{k} K_{\nu - n + 2 k}(z).
\end{equation}

\begin{equation}\label{eq:Airy_bound1}
\bigl|\uptext{Ai}^{(n)}(z)\bigr| \leq C(n) e^{- \frac{2}{3} z^{3/2}},
\end{equation}

\begin{equation}\label{eq:Airy_bound2}
\bigl|\uptext{Ai}^{(n)}(-z)\bigr| \leq C(n),
\end{equation}

\label{lem:S_integral_estimate}
For  $t > 0$, $L > 0$, $\bar L > 0$, $u \in \mathbb{R}$, $x \in \mathbb{R}$, and  integer $n \geq 0$,
\begin{equation}\label{eq:S_integral_estimate}
\bigl\| \bigl(\mathbf{S}^{(n)}_{t,x} \Gamma_t\bigr) (u, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|_{L^2} \leq C,
\end{equation}
for $|x| \leq L$ and $|u| \leq \bar L$, where the constant $C \geq 0$ depends on $n$, $t$, $L$ and $\bar L$. Here, $\mathbf{S}^{(n)}_{t,x}(z)$ is the $n^{\text{th}}$ derivative with respect to $z$; the multiplicative operator $\Gamma_t$ is defined in \eqref{eq:Gamma_L}.

\begin{equation}\label{eq:S_integral_estimate}
\bigl\| \bigl(\mathbf{S}^{(n)}_{t,x} \Gamma_t\bigr) (u, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|_{L^2} \leq C,
\end{equation}

The definition \eqref{eq:fTdef} yields $\mathbf{S}_{t,x}(z) = t^{-1/3} \mathbf{S}_{1, t^{-2/3} x}(t^{-1/3} z)$ for $t \neq 0$. This means that the bound \eqref{eq:S_integral_estimate} for any $t > 0$ follows from the same bound for $t = 1$. Recalling the definition of $\Gamma = \Gamma_1$ in \eqref{eq:Gamma_L}, we may write
\begin{equation}
\bigl\| \bigl(\mathbf{S}^{(n)}_{1,x} \Gamma\bigr) (u, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|^2_{L^2} = \int_{-\infty}^\infty \mathbf{S}^{(n)}_{1,x} (u - v)^2 e^{2 G(v)} \mathrm{d} v.
\end{equation}
Applying then the bound \eqref{eq:S_bound}, we get
\begin{align}
\MoveEqLeft
\bigl\| \bigl(\mathbf{S}^{(n)}_{1,x} \Gamma\bigr) (u, \mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}) \bigr\|^2_{L^2} \\
&\leq C_1 \int_{-\infty}^\infty \exp\left\{2 F(x,u - v) + 2 G(v)\right\} \mathrm{d} v \\
&= C_1 e^{\frac{4}{3} x^3 - 2 x u} \int_{-\infty}^\infty \exp\left\{- \frac{4}{3} ((x^2 - u + v) \vee 0)^{3/2} + 2 x v + 2 \kappa \mathrm{sgn}(v) |v|^{3/2}\right\} \mathrm{d} v,\label{eq:integral}
\end{align}
where the constant $C_1$ depends on $n$. In order to estimate this integral, we will split the interval of integration into two subintervals: $v \leq u - x^2$ and $v > u - x^2$.

If $v \leq u - x^2$ in the integral \eqref{eq:integral}, then, on this interval of integration, the expression \eqref{eq:integral} equals
\begin{equation}
C_1 e^{\frac{4}{3} x^3 - 2 x u} \int_{-\infty}^{(u - x^2) \wedge 0} \exp\left\{2 x v - 2 \kappa |v|^{3/2}\right\} \mathrm{d} v + C_1 e^{\frac{4}{3} x^3 - 2 x u} \int_{(u - x^2) \wedge 0}^{u - x^2} \exp\left\{2 x v + 2 \kappa |v|^{3/2}\right\} \mathrm{d} v.
\end{equation}
Naturally, for $|x| \leq L$ and $|u| \leq \bar L$, both these integrals are bounded by a constant depending on $L$ and $\bar L$.

In the case that $v > u - x^2$, the expression in \eqref{eq:integral} may be written as
\begin{equation}\label{eq:integral2}
\begin{split}
\MoveEqLeft
C_1 e^{\frac{4}{3} x^3 - 2 x u } \int_{u - x^2}^{(u - x^2) \vee 0} \exp\left\{- \frac{4}{3} (x^2 - u + v)^{3/2} + 2 x v - 2 \kappa |v|^{3/2}\right\} \mathrm{d} v \\
&+ C_1 e^{\frac{4}{3} x^3 - 2 x u} \int_{{(u - x^2) \vee 0}}^\infty \exp\left\{- \frac{4}{3} (x^2 - u + v)^{3/2} + 2 x v + 2 \kappa v^{3/2}\right\} \mathrm{d} v.
\end{split}
\end{equation}
For $|x| \leq L$ and $|u| \leq \bar L$, the first term in \eqref{eq:integral2} is bounded by a constant depending on $L$ and $\bar L$. Now, we will bound the second integral in \eqref{eq:integral2}. For this, we use the inequality
\begin{equation}
\tfrac{4}{3} (x^2 - u + v)^{\frac{3}{2}} \geq \alpha [(x^2 - u) \vee 0]^{\frac{3}{2}} + \bigl(\tfrac{4}{3} - \alpha\bigr) [v - (u - x^2) \vee 0]^{\frac{3}{2}},
\end{equation}
which holds for any $\alpha < \frac{4}{3}$. Then the second integral in \eqref{eq:integral2} is estimated by

\begin{align}
\MoveEqLeft
C_1 e^{\frac{4}{3} x^3 - 2 x u - \alpha [(x^2 - u) \vee 0]^{3/2}}\\
&\qquad\times \int_{{(u - x^2) \vee 0}}^\infty\exp\left\{- (\tfrac{4}{3} - \alpha) [v - (u - x^2) \vee 0]^{3/2} + 2 x v + 2 \kappa v^{3/2}\right\} \mathrm{d} v \\

&= C_1 e^{\frac{4}{3} x^3 - 2 x u - \alpha [(x^2 - u) \vee 0]^{3/2}}\\
&\qquad\times \int_{0}^\infty \exp\left\{- (\tfrac{4}{3} - \alpha) v^{3/2} + 2 x v + 2 \kappa (v + (u - x^2) \vee 0)^{3/2}\right\} \mathrm{d} v\\

&\leq C_1 e^{\frac{4}{3} x^3 - 2 x u - (\alpha - 2^{3/2} \kappa) [(x^2 - u) \vee 0]^{3/2}} \int_{0}^\infty \exp\left\{- (\tfrac{4}{3} - \alpha - 2^{3/2} \kappa) v^{3/2} + 2 x v\right\} \mathrm{d} v,
\end{align}

where in the last line we have used Jensen's inequality for the function $|\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette{\mathpalette\bigcdot@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}}@{.5}|^{3/2}$. As soon as $\kappa > 0$ is small enough, the last integral is bounded by a constant depending on $x$, which implies that the last term in \eqref{eq:integral2} is bounded by a constant depending on $L$ and $\bar L$, if $|x| \leq L$ and $|u| \leq \bar L$.

Combining \eqref{eq:integral} with the derived bounds, we obtain the bound \eqref{eq:S_integral_estimate} for $t = 1$, as required.

